/// <summary>
/// CB748_PricingConditions
/// </summary>
internal final class METPendingVendorInvoiceOffRemittanceRebate
{
    VendInvoiceInfoTable vendInvoiceInfoTable;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
protected void new(VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    vendInvoiceInfoTable = _vendInvoiceInfoTable;
}

/// <summary>
/// Construct
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
/// <returns>New instance of <c>METPendingVendorInvoiceOffRemittanceRebate</c></returns>
public static METPendingVendorInvoiceOffRemittanceRebate construct(VendInvoiceInfoTable _vendInvoiceInfoTable)
{        
    return new METPendingVendorInvoiceOffRemittanceRebate(_vendInvoiceInfoTable);
}

/// <summary>
/// Run method
/// </summary>
public void run()
{        
    #OCCRetryCount

    if (this.validate())
    {
        try
        {
            ttsbegin;
            this.process();
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }    
}

/// <summary>
/// Update tax amount for the variance line, overrides the calculated tax amount
/// </summary>
/// <param name = "_infoTable"><t>VendInvoiceInfoTable</t> buffer</param>
/// <param name = "_infoLine"><t>VendInvoiceInfoLine</t> table buffer</param>
/// <param name = "_gstVariance">tax variance amount</param>
private void adjustTaxAmountOnCharges()
{
    Tax tax;
    PurchTotals purchTotals = PurchTotals::newParmTable(
                            vendInvoiceInfoTable,
                            PurchUpdate::PackingSlip,
                            vendInvoiceInfoTable.ParmId,
                            '',
                            vendInvoiceInfoTable.Ordering);
    purchTotals.calc();
    tax = purchTotals.tax();

    VendInvoiceInfoLine infoLine;

    while select infoLine
        where infoLine.ParmId == vendInvoiceInfoTable.ParmId
        && infoLine.TableRefId == vendInvoiceInfoTable.TableRefId
    {
        MarkupTrans markupTrans;
        MarkupTable markupTable;
        while select markupTrans
            where markupTrans.TransTableId == infoLine.TableId
            && markupTrans.TransRecId == infoLine.RecId
            join markupTable
            where markupTable.MarkupCode == markupTrans.MarkupCode
            && markupTable.METIsOffRemittance
        {
            this.adjustTaxForMarkupTransaction(tax, markupTrans, infoLine, markupTable);
        }
    }

}

/// <summary>
/// Adjust tax for a single markup transaction
/// </summary>
/// <param name = "_tax">Tax object</param>
/// <param name = "_markupTrans">MarkupTrans record buffer</param>
/// <param name = "_infoline">VendInvoiceInfoLine buffer</param>
/// <param name = "_markupTable">MarkupTable buffer</param>
private void adjustTaxForMarkupTransaction(Tax _tax, MarkupTrans _markupTrans, VendInvoiceInfoLine _infoline, MarkupTable _markupTable)
{

    TaxRegulationDetail taxReg  = TaxRegulation::newTaxRegulation(_tax, null, _markupTrans.tableid, _markupTrans.Recid);

    TmpTaxRegulation tmpTaxReg = taxReg.tmpTaxRegulationDetail();
    TmpTaxRegulation tmpTaxRegInfoLine = taxReg.tmpTaxRegulationDetail();

    TmpTaxWorkTrans tmpTaxWorkTrans = taxReg.tmpTaxWorkTrans();

    select firstonly tmpTaxReg
        where tmpTaxReg.SourceRecId == _markupTrans.RecId &&
              tmpTaxReg.SourceTableId == _markupTrans.TableId;

    select firstonly tmpTaxRegInfoLine
        where tmpTaxRegInfoLine.SourceRecId == _infoline.RecId &&
              tmpTaxRegInfoLine.SourceTableId == _infoline.TableId;

    TaxItemGroup taxItemGroup = _markupTable.METFollowTransactionTaxItemGroup ? _infoline.TaxItemGroup : _markupTable.TaxItemGroup;

    TaxAmount taxAmt = Tax::calcTaxAmount(_markupTrans.TaxGroup, 
                                            taxItemGroup, 
                                            vendInvoiceInfoTable.TransDate, 
                                            tmpTaxRegInfoLine.SourceCurrencyCode, 
                                            tmpTaxRegInfoLine.ActualSourceRegulateAmountCur,
                                            TaxModuleType::PurchInvoice);

    select firstonly tmpTaxWorkTrans
        where tmpTaxWorkTrans.SourceRecId == _markupTrans.RecId &&
              tmpTaxWorkTrans.SourceTableId == _markupTrans.TableId;

    if (tmpTaxReg)
    {
        taxReg.updateTaxRegulationAmount(tmpTaxReg, taxAmt, true);
        taxReg.saveTaxRegulation();
        TaxIntegrationAdjustment::saveTaxAdjustment(_markupTrans.TableId, _markupTrans.RecId, tmpTaxWorkTrans, tmpTaxReg, true);
    }
}

/// <summary>
/// Create rebate charge codes
/// </summary>
protected void process()
{
    this.createRebateChargeCodes();   

    //CB748 - Off-Remittance vendor rebate tax adjustments
    this.adjustTaxAmountOnCharges();

    boolean isRebateChargeCode = vendInvoiceInfoTable.METCheckOffRemittanceChargeCodes();

    // set invoice on hold if parameter is ticked
    if (!isRebateChargeCode && METVendParameters::find().HoldInvoice)
    {
        vendInvoiceInfoTable.selectForUpdate(true);
        vendInvoiceInfoTable.Hold = NoYes::Yes;
        vendInvoiceInfoTable.update();
    }
}

/// <summary>
/// Validate
/// </summary>
/// <returns>True if validation successful; otherwise, false.</returns>
protected boolean validate()
{
    boolean ret = false;

    //only apply off remittance rebates if Enable vendor rebates parameter is yes
    if (METVendParameters::find().VendorRebatesEnabled
    && !vendInvoiceInfoTable.METReturnInvoice)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Create rebate charge codes for all pending vendor invoice lines before the invoice posting is submitted by workflow.
/// </summary>
/// <returns>True if rebate charge codes created; otherwise, false.</returns>
protected void createRebateChargeCodes()
{
    VendInvoiceInfoLine vendInvoiceInfoLine;
    VendInvoiceInfoTable vendInvoiceInfoTableLoop;

    // Loop through lines
    while select vendInvoiceInfoLine         
     exists join vendInvoiceInfoTableLoop
           where vendInvoiceInfoTableLoop.ParmId == vendInvoiceInfoTable.ParmId
              && vendInvoiceInfoTableLoop.TableRefId == vendInvoiceInfoTable.TableRefId
              && vendInvoiceInfoLine.ParmId     == vendInvoiceInfoTableLoop.ParmId 
              && vendInvoiceInfoLine.TableRefId == vendInvoiceInfoTableLoop.TableRefId
              // only trigger the off remittance charge codes creation for non CT or CD. Variance item off remittance charge codes are created when the line is inserted
              && (!vendInvoiceInfoTableLoop.METChargeThrough && !vendInvoiceInfoTableLoop.METCrossDock)
    {            
        // Trigger the new auto charge lines using the new logic (copied from vendInvoiceInfoLine\createMarkupTrans) and new parameter _metRebateCodes = true
        Markup::METInsertMarkupTrans(HeadingLine::Line,
                          MarkupModuleType::Vend,
                          vendInvoiceInfoLine,
                          vendInvoiceInfoTable.InvoiceAccount,
                          vendInvoiceInfoTable.MarkupGroup,
                          vendInvoiceInfoTable.CurrencyCode,
                          vendInvoiceInfoTable.vendTable_InvoiceAccount().languageId(),
                          vendInvoiceInfoLine.ItemId,
                          vendInvoiceInfoLine.inventTable().purchMarkupGroup(),
                         (vendInvoiceInfoLine.LineAmount < 0), // invert sign on creditnotes
                          false); // Added _deleteExistingMarkupTrans = false so it doesn't remove charge codes copied from PO at creation or non rebate charge codes           
    }
}
